import 'dart:async'; import 'package:flutter/material.dart'; import 'package:shared_preferences/shared_preferences.dart'; import '../../core/api.dart'; import '../../core/models.dart'; import '../details/details_page.dart';
class SearchPage extends StatefulWidget{const SearchPage({super.key,required this.api});final ApiClient api;@override State<SearchPage> createState()=>_SearchPageState();}
class _SearchPageState extends State<SearchPage>{final c=TextEditingController();Timer? timer;List<TitleItem> results=[];List<String> recent=[];bool loading=false;String error='';@override void initState(){super.initState();loadRecent();}Future<void> loadRecent()async{final p=await SharedPreferences.getInstance();if(mounted)setState(()=>recent=p.getStringList('recent_searches')??[]);}Future<void> saveRecent(String q)async{final p=await SharedPreferences.getInstance();recent=[q,...recent.where((x)=>x.toLowerCase()!=q.toLowerCase())].take(10).toList();await p.setStringList('recent_searches',recent);if(mounted)setState((){});}
void run(String q){timer?.cancel();error='';if(q.trim().isEmpty){setState(()=>results=[]);return;}timer=Timer(const Duration(milliseconds:450),()async{setState(()=>loading=true);try{final r=await widget.api.search(q.trim());await saveRecent(q.trim());if(mounted)setState(()=>results=r);}catch(_){if(mounted)setState(()=>results=widget.api.demoSearch(q.trim()));}finally{if(mounted)setState(()=>loading=false);}});}
Widget thumb(String u)=>SizedBox(width:58,height:78,child:u.startsWith('http')?Image.network(u,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const Icon(Icons.image)):Image.asset(u.isEmpty?'assets/images/common/anivortex_logo.png':u,fit:BoxFit.cover,errorBuilder:(_,__,___)=>const Icon(Icons.image)));
@override void dispose(){timer?.cancel();c.dispose();super.dispose();}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('Search')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[TextField(controller:c,onChanged:run,textInputAction:TextInputAction.search,decoration:InputDecoration(prefixIcon:const Icon(Icons.search),hintText:'Search anime, movies, TV shows...',suffixIcon:IconButton(onPressed:(){c.clear();run('');},icon:const Icon(Icons.clear)),border:const OutlineInputBorder())),if(loading)const LinearProgressIndicator(minHeight:2),if(error.isNotEmpty)Padding(padding:const EdgeInsets.all(8),child:Text(error)),if(results.isEmpty&&c.text.isEmpty&&recent.isNotEmpty)Expanded(child:ListView(children:[const Padding(padding:EdgeInsets.only(top:14,bottom:6),child:Text('Recent Searches',style:TextStyle(fontWeight:FontWeight.bold))),...recent.map((q)=>ListTile(leading:const Icon(Icons.history),title:Text(q),onTap:(){c.text=q;run(q);})),const SizedBox(height:10),const Text('Trending Search',style:TextStyle(fontWeight:FontWeight.bold)),Image.asset('assets/images/search/trending_searches.png',height:120,fit:BoxFit.contain)])) else Expanded(child:results.isEmpty?const Center(child:Text('No results found')):ListView.separated(itemCount:results.length,separatorBuilder:(_,__)=>const Divider(height:1),itemBuilder:(_,i){final x=results[i];return ListTile(leading:thumb(x.image),title:Text(x.name),subtitle:Text(x.subtitle,maxLines:2,overflow:TextOverflow.ellipsis),onTap:()=>Navigator.push(context,MaterialPageRoute(builder:(_)=>DetailsPage(title:x,api:widget.api))));}))])));
}
